repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('town', 6), ('city', 45), ('united', 57), ('rovers', 16), ('rovers', 20), ('united', 36), ('town', 43)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.ranking.py:
"""Top fixtures by goals."""


def _take_largest(fixtures):
    """Remove and return the fixture with the largest goals."""
    best = max(fixtures, key=lambda x: x.goals)
    fixtures.remove(best)
    return best


def podium(fixtures, places=3):
    """Return the top `places` fixtures by goals, largest first. The caller's list is left as it was."""
    top = []
    while fixtures and len(top) < places:
        top.append(_take_largest(fixtures))
    return top


def report(fixtures):
    """Return the podium values, the number of fixtures and every goals."""
    return {"podium": [x.goals for x in podium(fixtures)], "count": len(fixtures), "all": [x.goals for x in fixtures]}
